WITH flattened AS (SELECT id, plan, EXPLODE(tier_limits) AS element FROM price_tiers), with_windows AS (SELECT *, AVG(element) OVER w_recent AS plan_avg_element, AVG(element) OVER w_recent AS plan_avg_element_2, SUM(element) OVER w_recent AS plan_sum_element FROM flattened WINDOW w_recent AS (PARTITION BY plan)), enriched AS (SELECT id, plan, element, plan_avg_element, plan_avg_element_2, plan_sum_element, CUME_DIST() OVER (ORDER BY plan_avg_element_2 ASC) AS plan_avg_element_2_cume_dist, MAX(element) OVER (PARTITION BY plan) AS plan_max_element FROM with_windows), valid AS (SELECT *, CASE WHEN plan_avg_element_2_cume_dist >= 0.88 THEN 'High' WHEN plan_avg_element_2_cume_dist >= 0.39 THEN 'Medium' ELSE 'Low' END AS plan_avg_element_2_cume_dist_band FROM enriched WHERE plan_avg_element >= 61), cleaned AS (SELECT *, plan_avg_element * plan_avg_element_2 AS plan_avg_element_times_plan_avg_element_2, ROUND(plan_avg_element * 1.15, 2) AS plan_avg_element_scaled FROM valid WHERE plan_avg_element >= 77), enriched_price_tiers AS (SELECT id, plan, element, plan_avg_element, plan_avg_element_2, plan_sum_element, plan_avg_element_2_cume_dist, plan_max_element, plan_avg_element_2_cume_dist_band, plan_avg_element_times_plan_avg_element_2, plan_avg_element_scaled, RANK() OVER (ORDER BY element DESC NULLS LAST) AS element_rank, PERCENT_RANK() OVER (ORDER BY plan_avg_element_times_plan_avg_element_2 DESC NULLS LAST) AS plan_avg_element_times_plan_avg_element_2_percent_rank, DENSE_RANK() OVER w_hist AS plan_avg_element_scaled_dense_rank, MIN(plan_max_element) OVER (PARTITION BY plan) AS plan_min_plan_max_element, CUME_DIST() OVER (ORDER BY element DESC NULLS FIRST) AS element_cume_dist FROM cleaned WINDOW w_hist AS (PARTITION BY plan ORDER BY plan_avg_element_scaled DESC)), scored AS (SELECT id, plan, element, plan_avg_element, plan_avg_element_2, plan_sum_element, plan_avg_element_2_cume_dist, plan_max_element, plan_avg_element_2_cume_dist_band, plan_avg_element_times_plan_avg_element_2, plan_avg_element_scaled, element_rank, plan_avg_element_times_plan_avg_element_2_percent_rank, plan_avg_element_scaled_dense_rank, plan_min_plan_max_element, element_cume_dist, RANK() OVER (ORDER BY plan_avg_element_times_plan_avg_element_2_percent_rank ASC) AS plan_avg_element_times_plan_avg_element_2_percent_rank_rank, RANK() OVER (PARTITION BY plan ORDER BY plan_avg_element_times_plan_avg_element_2_percent_rank DESC NULLS FIRST) AS plan_avg_element_times_plan_avg_element_2_percent_rank_rank_2, RANK() OVER (PARTITION BY plan ORDER BY plan_max_element DESC) AS plan_max_element_rank, PERCENT_RANK() OVER (ORDER BY plan_avg_element ASC) AS plan_avg_element_percent_rank, MAX(element_cume_dist) OVER (PARTITION BY plan) AS plan_max_element_cume_dist FROM enriched_price_tiers) SELECT CASE WHEN element_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_rank_tier, plan, COUNT(*) AS cnt, COUNT_IF(plan = 'basic') AS basic_events, COUNT(*) AS num_rows, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM scored GROUP BY CUBE (CASE WHEN element_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, plan) HAVING num_rows >= 1;
